<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { useRoute } from 'vue-router';
import { Activity, History, Play, RefreshCw, Search } from '@lucide/vue';
import ObservabilityWorkspaceView from './ObservabilityWorkspaceView.vue';
import ServiceHealthBadge from '@/components/observability/ServiceHealthBadge.vue';
import InspectionRuns from '@/components/automation/InspectionRuns.vue';
import DetailPanel from '@/components/DetailPanel.vue';
import InlineError from '@/components/InlineError.vue';
import EmptyState from '@/components/EmptyState.vue';
import LoadingState from '@/components/LoadingState.vue';
import PaginationBar from '@/components/PaginationBar.vue';
import { observabilityApi, type InspectionItem, type InspectionSnapshot } from '@/api/observability';
import { useAuthStore } from '@/stores/auth';
import { observationTime, serviceContext } from '@/utils/observability';
const route = useRoute(); const auth = useAuthStore(); const data = ref<InspectionSnapshot>(); const loading = ref(false); const error = ref(''); const busy = ref(''); const page = ref(1); const search = ref(''); const onlyFailed = ref(false); const selected = ref<InspectionItem>(); const history = ref<InspectionItem[]>([]); const historyLoading = ref(false);
let epoch = 0; let historyEpoch = 0; let disposed = false; let timer: ReturnType<typeof setInterval> | undefined;
const environment = computed(() => String(route.query.environment || 'ALL')); const timeRange = computed(() => String(route.query.timeRange || '15m'));
const filtered = computed(() => (data.value?.items || []).filter(item => (!route.query.ciCode || item.ciCode === route.query.ciCode) && (!search.value || `${item.name} ${item.ciCode}`.toLowerCase().includes(search.value.toLowerCase())) && (!onlyFailed.value || item.result === 'ABNORMAL' || ['FAILED', 'CRITICAL', 'DEGRADED', 'ATTENTION', 'WARNING'].includes(item.status))));
const rows = computed(() => filtered.value.slice((page.value - 1) * 10, page.value * 10));
function executionLabel(value?: string) { return ({ NOT_RUN: '尚未执行', RUNNING: '执行中', COMPLETED: '执行完成', FAILED: '执行失败', SKIPPED: '已跳过', TIMED_OUT: '执行超时', LEGACY_RECORDED: '历史记录' } as Record<string, string>)[value || ''] || value || '执行状态未记录'; }
function resultLabel(value?: string) { return ({ PASS: '检查通过', ABNORMAL: '检查异常', UNKNOWN: '结论未知', NOT_APPLICABLE: '不适用' } as Record<string, string>)[value || ''] || value || '结论未记录'; }
function label(status: string) { return ({ NOT_RUN: '尚未执行', SUCCESS: '检查通过', WARNING: '需要关注', HEALTHY: '检查通过', SUCCEEDED: '检查通过', OK: '检查通过', CRITICAL: '检查失败', DEGRADED: '需要关注', FAILED: '检查失败', ATTENTION: '需要关注', UNKNOWN: '暂无有效结果', NOT_CONFIGURED: '未配置检查', MAINTENANCE: '维护中', DRILLING: '演练中' } as Record<string, string>)[status] || status; }
async function load() { const own = ++epoch; const token = auth.token; loading.value = true; error.value = ''; try { const value = await observabilityApi.inspections({ environment: environment.value, timeRange: timeRange.value }); if (!disposed && own === epoch && token === auth.token) data.value = value; } catch (cause) { if (!disposed && own === epoch) { data.value = undefined; error.value = cause instanceof Error ? cause.message : '巡检数据读取失败'; } } finally { if (own === epoch) loading.value = false; } }
async function showHistory(item: InspectionItem) { selected.value = item; history.value = []; const own = ++historyEpoch; historyLoading.value = true; try { const value = await observabilityApi.inspectionHistory(item.ciCode); if (!disposed && own === historyEpoch) history.value = value.items; } catch (cause) { if (!disposed && own === historyEpoch) error.value = cause instanceof Error ? cause.message : '历史读取失败'; } finally { if (own === historyEpoch) historyLoading.value = false; } }
async function run(item: InspectionItem) { if ((!auth.isAdmin && !auth.isOps && !auth.isDemo) || busy.value) return; const identity = auth.token; busy.value = item.ciCode; try { const result = await observabilityApi.runInspection(item.ciCode); if (!disposed && identity === auth.token) { await load(); await showHistory({ ...result, name: item.name, ciCode: item.ciCode }); } } catch (cause) { if (!disposed && identity === auth.token) error.value = cause instanceof Error ? cause.message : '检查执行失败'; } finally { if (!disposed) busy.value = ''; } }
watch(() => [route.query, auth.token], () => { epoch++; historyEpoch++; selected.value = undefined; history.value = []; data.value = undefined; if (auth.token) void load(); });
watch(() => [search.value, onlyFailed.value, route.query.ciCode], () => { page.value = 1; });
onMounted(() => { void load(); timer = setInterval(() => { if (!document.hidden && !loading.value && !busy.value) void load(); }, 15_000); });
onBeforeUnmount(() => { disposed = true; epoch++; historyEpoch++; clearInterval(timer); });
</script>
<template><ObservabilityWorkspaceView description="持续查看采集与业务检查结果，失败不等于已完成修复。"><template #actions><button class="button secondary" :disabled="loading" @click="load"><RefreshCw :size="16" />刷新结果</button><RouterLink class="button secondary" :to="{ path: '/automation', query: { ...route.query, tab: 'inspection' } }">查看巡检计划</RouterLink></template><InlineError v-if="error" :message="error" /><div v-if="data?.today" class="obs-wallboard-metrics"><article><span>今日服务检查</span><strong>{{ data.today.total || 0 }}</strong><small>持久化检查记录</small></article><article><span>检查通过</span><strong>{{ data.today.SUCCESS || 0 }}</strong><small>检查时刻结果</small></article><article><span>失败 / 需关注</span><strong>{{ (data.today.FAILED || 0) + (data.today.WARNING || 0) }}</strong><small>建议查看证据</small></article><article><span>未能确认</span><strong>{{ data.today.UNKNOWN || 0 }}</strong><small>数据或监控绑定缺失</small></article></div><div v-if="data?.schedule" class="obs-source-note"><strong>{{ data.schedule.enabled ? '自动巡检已启用' : '自动巡检已关闭' }}</strong><span>间隔 {{ Math.round(data.schedule.intervalMs / 1000) }} 秒</span><span>{{ data.schedule.enabled ? '下次计划：' + observationTime(data.schedule.nextRunAt) : data.schedule.reasonCode || '计划未启用，不会显示为检查通过' }}</span></div><section class="panel obs-inspections"><div class="obs-toolbar"><div class="search-box obs-service-search"><Search :size="16" /><input v-model="search" placeholder="搜索检查或服务" aria-label="搜索持续巡检" /></div><label class="obs-check"><input v-model="onlyFailed" type="checkbox" />只看失败 / 需关注</label><span class="obs-muted">{{ observationTime(data?.checkedAt) }} · 每 15 秒刷新</span></div><div v-if="route.query.ciCode" class="obs-edit-note">当前服务：{{ route.query.ciCode }}<RouterLink class="text-button" :to="{ path: '/observability/inspections', query: { environment, timeRange } }">查看全部服务</RouterLink></div><LoadingState v-if="loading && !data" text="读取持续巡检结果…" /><div v-else-if="rows.length" class="obs-table-scroll"><table class="obs-table"><thead><tr><th>检查 / 服务</th><th>上次检查 / 当前观测</th><th>连续失败</th><th>最近检查</th><th>操作</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ item.ciCode }}</small><p class="obs-inspection-summary">{{ item.summary }}</p></td><td><span class="obs-inspection-status" :class="{ failed: ['FAILED', 'CRITICAL'].includes(item.status), healthy: ['HEALTHY', 'SUCCEEDED', 'OK', 'SUCCESS'].includes(item.status) }">{{ item.executionStatus ? executionLabel(item.executionStatus) : label(item.status) }}</span><small v-if="item.result" class="obs-inspection-result">检查结论：{{ resultLabel(item.result) }}</small><div class="obs-current-health"><ServiceHealthBadge :health="item.currentHealth || 'UNKNOWN'" /></div></td><td>{{ item.consecutiveFailures ?? '—' }}</td><td>{{ observationTime(item.lastCheckedAt) }}</td><td><div class="row-actions"><button class="text-button" @click="showHistory(item)"><History :size="15" />历史</button><RouterLink class="text-button" :to="{ path: '/observability/topology', query: serviceContext(item.ciCode, environment, timeRange) }">服务拓扑</RouterLink><button v-if="auth.isAdmin || auth.isOps || auth.isDemo" class="text-button" :disabled="!!busy" @click="run(item)"><Play :size="15" />{{ busy === item.ciCode ? '检查中…' : '检查一次' }}</button></div></td></tr></tbody></table></div><EmptyState v-else :icon="Activity" title="暂无匹配检查" description="请调整服务或异常筛选；无有效数据时不会显示为检查通过。" /><PaginationBar v-if="filtered.length" :page="page" :page-size="10" :total="filtered.length" @change="page = $event" /></section><details class="panel obs-inspection-platform"><summary>平台巡检计划与步骤记录</summary><p class="obs-muted">复用已有只读巡检工作流，查看计划周期、历史步骤和原始证据。</p><InspectionRuns /></details><DetailPanel v-if="selected" :title="`${selected.name} · 检查历史`" :subtitle="selected.ciCode" @close="selected = undefined; historyEpoch++"><LoadingState v-if="historyLoading" text="读取历史检查…" /><div v-else-if="history.length" class="obs-inspection-history"><article v-for="(item, index) in history" :key="`${item.id}-${index}`"><span>{{ observationTime(item.lastCheckedAt) }}</span><strong>{{ item.executionStatus ? executionLabel(item.executionStatus) : label(item.status) }}{{ item.result ? ' · ' + resultLabel(item.result) : '' }}</strong><p>{{ item.summary }}</p><div v-if="item.evidence" class="obs-source-note"><span>采样：{{ observationTime(item.evidence.observedAt) }}</span><span>活动告警：{{ item.evidence.activeAlertCount ?? '未获取' }}</span><span>{{ item.evidence.coverage }}</span></div><p class="obs-muted" v-if="item.runId || item.reasonCode">运行 {{ item.runId || '未记录' }} · {{ item.reasonCode || '' }}<br />开始 {{ observationTime(item.startedAt) }} · 完成 {{ observationTime(item.finishedAt) }}</p><small>来源：{{ item.source || '实际检查' }} · 连续失败 {{ item.consecutiveFailures ?? '—' }}</small></article></div><EmptyState v-else title="暂无历史检查记录" description="后续检查结果将在这里形成时间顺序。" /></DetailPanel></ObservabilityWorkspaceView></template>
